-- GATE PACK 0272 guard_trigger (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select t.tgname || '.' || w.k as k, w.v
from pg_catalog.pg_trigger t
cross join lateral (values ('row', ((t.tgtype & 1) = 1)::text), ('before', ((t.tgtype & 2) = 2)::text), ('enabled', t.tgenabled::text),
  ('events', concat_ws(',', case when (t.tgtype & 4) <> 0 then 'insert' end, case when (t.tgtype & 8) <> 0 then 'delete' end, case when (t.tgtype & 16) <> 0 then 'update' end)),
  ('function', (select p.proname from pg_catalog.pg_proc p where p.oid = t.tgfoid))) as w(k, v)
where t.tgrelid = pg_catalog.to_regclass('public.client_legal_identities') and not t.tgisinternal and t.tgname = 'client_legal_identities_guard'
order by 1;
